public static boolean isDigits(String str) {
    if (str == null || str.isEmpty()) {
        return false;
    }
    int len = str.length();
    for (int i = 0; i < len; ) {
        int cp = str.codePointAt(i);
        if (!Character.isDigit(cp)) {
            return false;
        }
        i += Character.charCount(cp);
    }
    return true;
}

codes:
public static boolean isDigits(String str) {
    if (str == null || str.isEmpty()) {
        return false;
    }
    int len = str.length();
    for (int i = 0; i < len; ) {
        int cp = str.codePointAt(i);
        if (!Character.isDigit(cp)) {
            return false;
        }
        i += Character.charCount(cp);
    }
    return true;
}

