public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new NullPointerException("Array is null");
    }
    int len = arr.length;
    if (from < 0 || to >= len || from > to) {
        throw new IllegalArgumentException("Invalid range");
    }
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

