    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        return;
    }
    Set<Integer> srcSet = bucketsByLabel.get(minLabel);
    if (srcSet == null || srcSet.isEmpty()) {
        return;
    }
    Set<Integer> destSet = bucketsByLabel.get(0);
    if (destSet == null) {
        destSet = new HashSet<>();
        bucketsByLabel.set(0, destSet);
    }
    for (Integer vertex : srcSet) {
        destSet.add(vertex);
        if (vertex != null && vertex >= 0 && vertex < labels.size()) {
            labels.set(vertex, 0);
